//
//  T3ExtensionFiles.swift
//  leanring-buddy
//
//  The T3 Code extension (a Claude plugin marketplace with the "theo" plugin:
//  skills plus the MCP launcher), written to Application Support by Setup.
//  Generated from ~/Projects/claudia-t3-plugin; regenerate after changing it.
//

enum T3ExtensionFiles {
    /// Relative path → contents. bin/ files are made executable.
    static let files: [String: String] = [
        ".claude-plugin/marketplace.json": "{\n  \"name\": \"theo\",\n  \"owner\": {\n    \"name\": \"Theo\"\n  },\n  \"metadata\": {\n    \"description\": \"Theo for T3 Code: her notes, screenshots, whiteboards and research for your coding agents.\"\n  },\n  \"plugins\": [\n    {\n      \"name\": \"theo\",\n      \"source\": \"./plugins/theo\",\n      \"description\": \"Theo, your on-screen Mac companion, inside T3 Code: her notes, marked screenshots, whiteboards and research for your coding agents, and \\\"ask Theo\\\".\"\n    }\n  ]\n}",
        "plugins/theo/.claude-plugin/plugin.json": "{\n  \"name\": \"theo\",\n  \"version\": \"1.0.0\",\n  \"description\": \"Theo inside T3 Code: use her notes, marked screenshots, whiteboards and research in coding, or hand her a request.\",\n  \"author\": { \"name\": \"Theo\" }\n}\n",
        "plugins/theo/.mcp.json": "{\n  \"mcpServers\": {\n    \"theo\": {\n      \"command\": \"${CLAUDE_PLUGIN_ROOT}/bin/theo-mcp\",\n      \"args\": []\n    }\n  }\n}\n",
        "plugins/theo/bin/theo-mcp": "#!/bin/bash\n# Starts Theo's MCP server (the Theo app run with --mcp). It talks to the running\n# Theo through its control inbox, so Theo must be open on this Mac.\n# Prefer the Theo that's running, then /Applications, then the newest copy found.\nrunning=$(ps -axo comm= | grep -E '\\.app/Contents/MacOS/Clicky$' | grep -v '\\.Trash' | head -1)\n[ -n \"$running\" ] && [ -x \"$running\" ] && exec \"$running\" --mcp\nfor bin in /Applications/Theo.app/Contents/MacOS/Clicky /Applications/Claudia.app/Contents/MacOS/Clicky /Applications/Clicky.app/Contents/MacOS/Clicky \"$HOME/Applications/Claudia.app/Contents/MacOS/Clicky\" \"$HOME/Applications/Clicky.app/Contents/MacOS/Clicky\"; do\n  [ -x \"$bin\" ] && exec \"$bin\" --mcp\ndone\nnewest=$(mdfind \"kMDItemCFBundleIdentifier == 'com.personal.clicky'\" 2>/dev/null | grep '\\.app$' | grep -v '\\.Trash' |\n  while read -r app; do [ -x \"$app/Contents/MacOS/Clicky\" ] && echo \"$(stat -f %m \"$app/Contents/MacOS/Clicky\") $app/Contents/MacOS/Clicky\"; done |\n  sort -rn | head -1 | cut -d' ' -f2-)\n[ -n \"$newest\" ] && exec \"$newest\" --mcp\necho \"Theo isn't installed on this Mac.\" >&2\nexit 1\n",
        "plugins/theo/skills/ask-theo/SKILL.md": "---\nname: ask-theo\ndescription: Hand a request to Theo, the user's on-screen Mac companion, who can see their screens, point and mark things, draw a whiteboard or flowchart, research, and talk. Use when the user says \"ask Theo\", \"have Theo show me\", \"draw a flowchart\", or wants something explained on their screen.\n---\n\n# Ask Theo\n\nTheo runs on the user's Mac and answers with her own brain: spoken, with marks on the real screen, a whiteboard or an editable flowchart, or research.\n\n- To hand her a request, call `claudia_ask` with the user's words as `text`. Set `speak: false` if the user wants it silent.\n- To show something yourself, call `claudia_see_screen` for element ids, then `claudia_show` with `[POINT:<id>]` or `[MARK:<n>:<id>:<label>|<note>]` tags.\n- For research across pages, call `claudia_research` with a question or urls. The brief opens in her notes.\n- To work the whiteboard (next, back, replay, expand, close, export), call `claudia_whiteboard`.\n\nTell the user in one line what Theo is doing. If a tool says Theo isn't running, ask them to open the Theo app.\n",
        "plugins/theo/skills/theo-notes/SKILL.md": "---\nname: theo-notes\ndescription: Use Theo's notes, research briefs, whiteboards and marked screenshots in this coding task. Use when the user says \"use my notes\", \"use Theo's notes\", \"use the screenshot I marked\", or picked notes for code in Theo.\n---\n\n# Use Theo's notes in code\n\nTheo keeps the user's notes (article notes, research briefs, whiteboards, and screenshots with numbered marks). In Theo's Notes tab the user ticks the ones to \"use in code\".\n\n1. Call the `claudia_attachments` tool. It returns the picked notes as Markdown and the picked screenshots and whiteboards as images.\n2. If nothing is picked, tell the user to tick notes in Theo's Notes tab (or in T3 Code + Theo's notes button), then stop.\n3. Treat the notes as the user's requirements and reference material: copy, facts, steps and layout. Treat a marked screenshot as a visual spec: the numbered marks point at the parts the user cares about.\n4. Say in one line which notes and screenshots you used, then do the coding task.\n",
        "plugins/theo/skills/theo-screen/SKILL.md": "---\nname: theo-screen\ndescription: Look at the user's screens through Theo (screenshots plus a list of on-screen elements) and point at or mark things on the real screen. Use when the user says \"look at my screen\", \"what's on my screen\", or \"show me where\".\n---\n\n# See and mark the screen with Theo\n\n1. Call `claudia_see_screen`. You get a screenshot of each screen (screen1 has the pointer) and a numbered list of on-screen elements with ids.\n2. Answer from what you see. To point, call `claudia_show` with `[POINT:<id>]`. For steps, use `[MARK:<n>:<id>:<label>|<short note>]` for each, in order. Theo flies her spark there and draws the marks.\n3. Keep spoken words short; the marks carry the detail.\n",
        "plugins/theo/skills/theo-whiteboard/SKILL.md": "---\nname: theo-whiteboard\ndescription: Have Theo draw or edit a flowchart, diagram or mind map on her whiteboard, or step through, export or close the open board. Use when the user asks for a flowchart, diagram, or to change the one on screen.\n---\n\n# Theo's whiteboard\n\n- New board: call `claudia_ask` with the request, e.g. \"draw a flowchart of the signup flow: sign up, verify email, pick a plan, pay\".\n- Edit the open board: call `claudia_ask` with the change, e.g. \"add a welcome email after verify and make pay green\". She redraws the same board in place.\n- Control it: `claudia_whiteboard` with `next`, `back`, `replay`, `pause`, `expand`, `close`, `export` (PDF + PNG) or `state`.\n- To use a board in code, export it, or have the user tick it in Theo's Notes and use the theo-notes skill.\n",
    ]
}
